  function order(records){return [...records].sort((a,b)=>{const x=info(a).sequence,y=info(b).sequence;if(x&&y)return x-y;if(x||y)return x?-1:1;return b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt);});}
  function setup(k){const shortGrip=(k.baseGrip||'未記録').replace(/（原資料：[^）]*）/g,'').replace('なし（元グリップ剥がし後）','なし');return `<span class="hl-setup">${E([k.state==='ready'?'張り上げ＋OG':M.states[k.state]||'未確認',`元：${shortGrip}`,`OG：${k.overgrip||(k.state==='ready'?'あり・品名未記録':'未記録')}`,k.custom&&k.custom!==title(k)&&k.custom!==info(k).condition?'施工：'+k.custom:'',k.stringMain?'縦：'+k.stringMain:'',k.stringCross?'横：'+k.stringCross:'',K(k.tensionMain)?`テンション：${k.tensionMain}${K(k.tensionCross)?'/'+k.tensionCross:''} ${k.tensionUnit}`:''].filter(Boolean).join(' ／ '))}</span>`;}
